using System;
using System.Drawing;
using System.Globalization;
using System.Windows.Forms;
class GifInspector:Panel {
 TextBox start,end,size,fps,repeat,customCrop,customAspect;Choice dimension,crop,aspect,palette,profile;Slider rate;Label limit;GlowButton advanced,editor,fromHere,toHere;bool expanded,loading;GifOptions original=new GifOptions();public Func<double> CurrentPosition;public event EventHandler EditRequested;public event EventHandler HeightChanged;public int RequiredHeight{get;private set;}
 public GifInspector(){BackColor=Skin.Card;start=Field("0");end=Field("5");size=Field("800");fps=Field("10");repeat=Field("0");customCrop=Field("7:5");customAspect=Field("7:5");dimension=Select(new[]{"По ширине","По высоте"});var ratios=new string[GifOptions.Ratios.Length];for(int i=0;i<ratios.Length;i++)ratios[i]=i==0?"Не менять":i==ratios.Length-1?"Своё соотношение…":GifOptions.Ratios[i];aspect=Select(ratios);var cropNames=new string[ratios.Length+1];cropNames[0]="Нет";cropNames[1]="Убрать чёрные поля";for(int i=1;i<ratios.Length;i++)cropNames[i+1]=ratios[i];crop=Select(cropNames);palette=Select(new[]{"Каждый кадр","Общая палитра","Bayer"});profile=Select(new[]{"Без лимита","До 10 МБ"});rate=new Slider{Minimum=1,Maximum=50,Value=10,BackColor=Skin.Card};Controls.Add(rate);limit=Skin.Label("",0,0,280,22,8.5f,false);limit.ForeColor=Skin.Muted;Controls.Add(limit);advanced=new GlowButton{Text="Дополнительные настройки"};editor=new GlowButton{Text="Полный редактор GIF…"};fromHere=new GlowButton{Text="← Текущая позиция",Font=new Font("Segoe UI",8)};toHere=new GlowButton{Text="Текущая позиция →",Font=new Font("Segoe UI",8)};Controls.Add(advanced);Controls.Add(editor);Controls.Add(fromHere);Controls.Add(toHere);fromHere.Click+=(s,e)=>start.Text=GifOptions.N(CurrentPosition==null?0:CurrentPosition());toHere.Click+=(s,e)=>end.Text=GifOptions.N(CurrentPosition==null?0:CurrentPosition());editor.Click+=(s,e)=>{if(EditRequested!=null)EditRequested(this,EventArgs.Empty);};advanced.Click+=(s,e)=>{expanded=!expanded;Arrange();if(HeightChanged!=null)HeightChanged(this,EventArgs.Empty);};rate.ValueChanged+=(s,e)=>fps.Text=rate.Value.ToString();fps.TextChanged+=(s,e)=>{int n;if(int.TryParse(fps.Text,out n)&&n>=1&&n<=50){rate.Value=n;UpdateLimit(n);}};crop.SelectedIndexChanged+=(s,e)=>{if(!loading){Arrange();if(HeightChanged!=null)HeightChanged(this,EventArgs.Empty);}};aspect.SelectedIndexChanged+=(s,e)=>{if(!loading){Arrange();if(HeightChanged!=null)HeightChanged(this,EventArgs.Empty);}};LoadOptions(original);}
 TextBox Field(string value){var frame=new InputFrame{BackColor=Skin.Card};var box=new TextBox{Text=value,BorderStyle=BorderStyle.None,AutoSize=false,BackColor=Skin.Card,ForeColor=Skin.Text,Font=new Font("Segoe UI",10)};frame.Controls.Add(box);Controls.Add(frame);return box;}
 Choice Select(string[] values){var c=new Choice{Font=new Font("Segoe UI",9)};c.Items.AddRange(values);Controls.Add(c);return c;}
 void Put(TextBox text,int x,int y,int w){text.Parent.SetBounds(x,y,w,38);text.SetBounds(12,9,Math.Max(1,w-24),22);}
 void Label(Graphics g,string text,int x,int y,int w){TextRenderer.DrawText(g,text,Font,new Rectangle(x,y,w,22),Skin.Muted,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
 void UpdateLimit(int n){limit.Text="До "+(600d/n).ToString("0.##")+" с · 600 кадров";double a,b;if(double.TryParse(start.Text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out a)&&double.TryParse(end.Text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out b)&&b-a>600d/n)end.Text=GifOptions.N(a+600d/n);}
 public void LoadOptions(GifOptions options){loading=true;original=options.Copy();start.Text=GifOptions.N(options.Start);end.Text=GifOptions.N(options.End);size.Text=options.Size.ToString();fps.Text=options.Fps.ToString();repeat.Text=options.Loop.ToString();dimension.SelectedIndex=options.Dimension;crop.SelectedIndex=options.Crop==0?0:options.Crop==-1?1:options.Crop+1;aspect.SelectedIndex=options.Aspect;palette.SelectedIndex=options.Method;profile.SelectedIndex=options.MaxBytes>0?1:0;customCrop.Text=options.CustomCrop;customAspect.Text=options.CustomAspect;UpdateLimit(options.Fps);loading=false;Arrange();}
 static double Number(string text){double n;if(!double.TryParse(text.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out n)||double.IsNaN(n)||double.IsInfinity(n))throw new Exception("Введите корректное время в секундах.");return n;}
 public GifOptions ReadOptions(){var o=original.Copy();o.Start=Number(start.Text);o.End=Number(end.Text);o.Size=int.Parse(size.Text);o.Fps=int.Parse(fps.Text);o.Loop=int.Parse(repeat.Text);o.Dimension=dimension.SelectedIndex;o.Crop=crop.SelectedIndex==0?0:crop.SelectedIndex==1?-1:crop.SelectedIndex-1;o.Aspect=aspect.SelectedIndex;o.Method=palette.SelectedIndex;o.MaxBytes=profile.SelectedIndex==1?10*1024*1024:0;o.CustomCrop=customCrop.Text;o.CustomAspect=customAspect.Text;o.Validate();o.CropRatio();o.AspectRatio();return o;}
 protected override void OnResize(EventArgs e){base.OnResize(e);Arrange();}
 int cropY,repeatY,advancedY,aspectY,methodY;
 void Arrange(){if(advanced==null)return;int w=Math.Max(200,Width),half=(w-12)/2;Put(start,0,26,half);Put(end,half+12,26,half);fromHere.SetBounds(0,70,half,30);toHere.SetBounds(half+12,70,half,30);dimension.SetBounds(0,134,half+24,38);Put(size,half+36,134,w-half-36);Put(fps,w-76,210,76);rate.SetBounds(0,210,w-90,38);limit.SetBounds(0,254,w,22);crop.SetBounds(0,308,w,38);cropY=282;int y=360;bool ownCrop=crop.SelectedIndex==GifOptions.Ratios.Length;customCrop.Parent.Visible=ownCrop;if(ownCrop){Put(customCrop,0,y,w);y+=52;}repeatY=y;Put(repeat,0,y+26,half);profile.SetBounds(half+12,y+26,half,38);y+=78;advancedY=y;advanced.SetBounds(0,y,w,38);y+=50;aspect.Visible=palette.Visible=expanded;bool ownAspect=expanded&&aspect.SelectedIndex==GifOptions.Ratios.Length-1;customAspect.Parent.Visible=ownAspect;aspectY=y;methodY=y;if(expanded){aspect.SetBounds(0,y+25,w,38);y+=76;if(ownAspect){Put(customAspect,0,y,w);y+=52;}methodY=y;palette.SetBounds(0,y+25,w,38);y+=76;}editor.SetBounds(0,y,w,40);RequiredHeight=y+50;Invalidate();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);int w=Width,half=(w-12)/2;Label(e.Graphics,"Начало, с",0,0,half);Label(e.Graphics,"Конец, с",half+12,0,half);Label(e.Graphics,"Размер",0,108,w);Label(e.Graphics,"Частота кадров · FPS",0,184,w);Label(e.Graphics,"Обрезка",0,cropY,w);Label(e.Graphics,"Повторы · 0 = ∞",0,repeatY,half);Label(e.Graphics,"Профиль",half+12,repeatY,half);if(expanded){Label(e.Graphics,"Пропорции · добавить поля",0,aspectY,w);Label(e.Graphics,"Палитра",0,methodY,w);}}
}
